/// Why a decode loop stopped early, checked cooperatively at the top of every
/// generated-token step (one relaxed atomic load + one clock read per token).
enum GenerationStopCause {
    /// The request's `CancellationToken` fired — the handler frame that owned
    /// this generation is gone (client disconnect, handler drop).
    Cancelled,
    /// The engine-enforced wall-clock deadline passed. Replaces the old
    /// handler-side `tokio::time::timeout`, which detached (but could not
    /// stop) the blocking decode.
    TimedOut,
}

/// Cooperative stop signal + engine-enforced deadline for one generation.
/// The token is fired by `CancelOnDrop` when the owning handler frame drops;
/// the deadline is armed by `generate_decoded_tokens_blocking` from
/// `CAMELID_GENERATION_TIMEOUT_MS`. The decode loop itself observes both, so
/// compute always stops within one token step of either trip — the handler
/// never detaches a running decode.
#[derive(Clone)]
struct GenerationCancel {
    token: tokio_util::sync::CancellationToken,
    deadline: Option<Instant>,
    timeout: Duration,
    started: Instant,
}

impl GenerationCancel {
    fn unbounded() -> Self {
        Self {
            token: tokio_util::sync::CancellationToken::new(),
            deadline: None,
            timeout: Duration::ZERO,
            started: Instant::now(),
        }
    }

    /// Arm the wall-clock deadline at decode entry (same coverage as the old
    /// handler-side timer: prep/tokenization are not counted).
    fn arm(&mut self, timeout: Duration) {
        self.started = Instant::now();
        self.timeout = timeout;
        self.deadline = self.started.checked_add(timeout);
    }

    fn tripped(&self) -> Option<GenerationStopCause> {
        if self.token.is_cancelled() {
            return Some(GenerationStopCause::Cancelled);
        }
        match self.deadline {
            Some(deadline) if Instant::now() >= deadline => Some(GenerationStopCause::TimedOut),
            _ => None,
        }
    }
}

/// RAII: fires the generation's CancellationToken when the owning frame is
/// dropped for ANY reason — client disconnect (hyper drops the handler
/// future), panic, or normal return (harmless then; the token is no longer
/// read). This is the Rust equivalent of llama.cpp's
/// `~server_response_reader → stop() → SERVER_TASK_TYPE_CANCEL`.
struct CancelOnDrop(tokio_util::sync::CancellationToken);

impl Drop for CancelOnDrop {
    fn drop(&mut self) {
        self.0.cancel();
    }
}

/// Response for a decode stopped by cancellation. Never delivered to the
/// (already disconnected) client; observable only in logs and tests.
fn generation_cancelled_response(generated_tokens: usize) -> Box<Response> {
    Box::new(api_error(
        StatusCode::SERVICE_UNAVAILABLE,
        "generation_cancelled",
        format!(
            "generation stopped after {generated_tokens} tokens: the request was cancelled before the decode finished"
        ),
        None,
    ))
}

struct PreparedGeneration {
    /// Prevent unload or deletion while preparation/decode owns file-backed
    /// model state. Test-only synthetic generations do not need a lease.
    _model_file_lease: Option<tokio::sync::OwnedRwLockReadGuard<()>>,
    model_id: String,
    model_path: PathBuf,
    token_ids: Vec<u32>,
    max_tokens: u32,
    tokenizer: Arc<Tokenizer>,
    session: LlamaInferenceSession,
    sampling: SamplingConfig,
    /// Stop signal + deadline observed at the top of every decode step.
    cancel: GenerationCancel,
    /// When set, collect per-token logprobs each step (chosen + this many top
    /// alternatives). Forces the full-host-logits decode path (no GPU greedy-fast).
    logprobs_top_n: Option<usize>,
    /// Active output constraint (`response_format` json_object / json_schema): each
    /// step is masked to tokens that keep a valid prefix of the constrained value.
    /// Forces the full-logits CPU decode path.
    constraint: Option<crate::grammar::ConstraintSpec>,
    stop_sequences: Vec<String>,
    logit_diagnostic_token_ids: Vec<u32>,
    collect_dense_diagnostics: bool,
    dense_diagnostic_generated_index: Option<usize>,
    dense_metadata: DenseDiagnosticMetadata,
    timings: GenerationTimings,
    cached_prompt_prefix: Arc<Mutex<PromptPrefixCachePool>>,
    metrics: metrics::ServerMetrics,
    engine_progress: engine::EngineHandle,
    speculative: Option<PreparedSpeculative>,
    /// Captured request identity for the live telemetry stream; taken by the
    /// generation path that actually runs (streaming or blocking).
    telemetry: Option<telemetry::RequestStart>,
}

/// Server-level speculative decoding mode (`CAMELID_SPEC_DECODE`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SpecDecodeMode {
    NGram,
    DraftModel,
}

fn spec_decode_mode_from_env() -> Option<SpecDecodeMode> {
    match env::var(SPEC_DECODE_ENV) {
        Ok(value) if value.eq_ignore_ascii_case("ngram") => Some(SpecDecodeMode::NGram),
        Ok(value) if value.eq_ignore_ascii_case("draft") => Some(SpecDecodeMode::DraftModel),
        _ => None,
    }
}

/// Run speculative decode on the GPU (CAMELID_SPEC_GPU=1): keep the target's
/// resident decode engine active during speculation and verify drafts via the
/// batched GPU `verify_batch` instead of the CPU chunk verify. Opt-in while this
/// lands; lossless either way (the target verify is authoritative), so the flag
/// only changes where the work runs.
fn spec_gpu_enabled() -> bool {
    matches!(
        env::var("CAMELID_SPEC_GPU").ok().as_deref(),
        Some("1") | Some("true") | Some("on") | Some("yes")
    )
}

fn spec_draft_tokens_from_env(default: usize) -> usize {
    env::var(SPEC_DRAFT_TOKENS_ENV)
        .ok()
        .and_then(|value| value.trim().parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(default)
}

fn spec_ngram_min_from_env() -> usize {
    env::var(SPEC_NGRAM_MIN_ENV)
        .ok()
        .and_then(|value| value.trim().parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(DEFAULT_NGRAM_MIN_MATCH)
}

fn spec_ngram_max_from_env() -> usize {
    env::var(SPEC_NGRAM_MAX_ENV)
        .ok()
        .and_then(|value| value.trim().parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(DEFAULT_NGRAM_MAX_MATCH)
}

fn prompt_prefix_cache_min_tokens_from_env() -> usize {
    env::var(PROMPT_PREFIX_CACHE_MIN_TOKENS_ENV)
        .ok()
        .and_then(|value| value.trim().parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(DEFAULT_PROMPT_PREFIX_CACHE_MIN_TOKENS)
}

/// Per-request speculative decoding state: the drafter plus round counters
/// for the end-of-request acceptance summary.
struct PreparedSpeculative {
    drafter: SpeculativeDrafter,
    draft_tokens: usize,
    latch: SpecLatch,
    rounds: u64,
    drafted: u64,
    accepted_drafts: u64,
}

/// One token's logprob plus its decoded piece and raw UTF-8 bytes (OpenAI-shaped).
#[derive(Debug, Clone)]
struct TokenLogprob {
    token: String,
    logprob: f32,
    bytes: Vec<u8>,
}

/// Per generated-token logprob record: the chosen token plus the top-N
/// alternatives by probability. Collected only when logprobs are requested.
#[derive(Debug, Clone)]
struct StepLogprob {
    chosen: TokenLogprob,
    top: Vec<TokenLogprob>,
}

struct GeneratedText {
    text: String,
    prompt_token_ids: Vec<u32>,
    generated_token_ids: Vec<u32>,
    dense_metadata: DenseDiagnosticMetadata,
    top_logits: Vec<LogitDiagnostic>,
    step_top_logits: Vec<Vec<LogitDiagnostic>>,
    /// Per-token logprobs (chosen + top-N); empty unless logprobs were requested.
    step_logprobs: Vec<StepLogprob>,
    output_projection: Vec<LlamaOutputProjectionDiagnostic>,
    dense: Option<LlamaForwardDiagnostics>,
    dense_diagnostic_generated_index: Option<usize>,
    completion_tokens: usize,
    finish_reason: &'static str,
    timings: GenerationTimings,
    /// Execution-trace rollup `(digest, fold_count)` from a deterministic run, else `None`.
    execution_trace: Option<(String, u64)>,
}

struct GeneratedTokens {
    prompt_token_ids: Vec<u32>,
    token_ids: Vec<u32>,
    dense_metadata: DenseDiagnosticMetadata,
    top_logits: Vec<RawLogitDiagnostic>,
    step_top_logits: Vec<Vec<RawLogitDiagnostic>>,
    /// Per-token logprobs (chosen + top-N); empty unless logprobs were requested.
    step_logprobs: Vec<StepLogprob>,
    output_projection: Vec<LlamaOutputProjectionDiagnostic>,
    dense: Option<LlamaForwardDiagnostics>,
    dense_diagnostic_generated_index: Option<usize>,
    finish_reason: &'static str,
    timings: GenerationTimings,
    /// Execution-trace rollup `(digest, fold_count)` captured during a deterministic run, or
    /// `None` when the trace was not armed (any non-deterministic generation).
    execution_trace: Option<(String, u64)>,
}

fn collect_dense_diagnostics_for_generated_index(
    prepared: &PreparedGeneration,
    generated_index: usize,
) -> bool {
    if !prepared.collect_dense_diagnostics {
        return false;
    }
    prepared
        .dense_diagnostic_generated_index
        .map(|target| target == generated_index)
        .unwrap_or(true)
}

#[derive(Clone)]
struct RawLogitDiagnostic {
    token_id: u32,
    logit: f32,
    probability: f32,
    rank: usize,
    selected: bool,
}

#[derive(Debug, Serialize)]
pub struct ErrorEnvelope {
    pub error: ErrorBody,
    /// Exact rendered prompt size for the typed prompt-limit error. This lets a
    /// count-only preflight trim optional context without weakening the normal
    /// generation ceiling. Other errors omit the field and remain fatal.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub prompt_token_count: Option<usize>,
}

#[derive(Debug, Serialize)]
pub struct ErrorBody {
    pub message: String,
    #[serde(rename = "type")]
    pub error_type: &'static str,
    pub code: &'static str,
    pub param: Option<&'static str>,
}

/// Structured API error metadata retained in a response extension. Streaming
/// handlers have already committed HTTP/SSE headers when a decode step fails,
/// so they cannot forward the response body; this copy preserves the original
/// machine-readable code and actionable message for the SSE error event.
#[derive(Clone, Debug, PartialEq, Eq)]
struct ApiErrorDetails {
    code: String,
    message: String,
}

/// The models directory used when `serve` gets no `--models-dir`: the first
/// existing of `<exe dir>/models` (the shipped layout — `camelid.exe` beside a
/// `models/` folder, the same precedent `auto_select_model` follows) then
/// `./models`, falling back to `./models` when neither exists yet.
fn default_models_dir() -> PathBuf {
    if let Ok(exe) = std::env::current_exe() {
        if let Some(dir) = exe.parent() {
            let beside = dir.join("models");
            if beside.is_dir() {
                return beside;
            }
        }
    }
    PathBuf::from("models")
}

/// Resolve the configured (or defaulted) models directory to an absolute path
/// once at startup, so it stays stable regardless of the launch-context CWD.
/// Uses `std::path::absolute`, NOT `fs::canonicalize`, deliberately: it does
/// not require the directory to exist yet (a fresh install has no models/ until
/// the first download) and never produces the Windows `\\?\` verbatim prefix in
/// user-facing strings.
fn resolve_models_dir(configured: Option<PathBuf>) -> PathBuf {
    let dir = configured.unwrap_or_else(default_models_dir);
    if dir.is_absolute() {
        dir
    } else {
        std::path::absolute(&dir).unwrap_or(dir)
    }
}

/// Resolve a model path from an API request against the configured models
/// directory. Order (first hit wins; nothing is ever rewritten once found):
///
/// 1. An ABSOLUTE path is used exactly as given (unchanged behavior).
/// 2. A relative path keeps its exact historical meaning first: as given,
///    against the process CWD.
/// 3. Otherwise `<models_dir>/<path>` — the fallback that makes relative loads
///    work when the server's CWD is arbitrary (the desktop sidecar case).
/// 4. Otherwise, when the request already leads with either the legacy API
///    prefix `models/` or the configured models dir's own folder name, that
///    leading component is stripped: `<models_dir>/foo.gguf`. The literal
///    prefix matters for custom stores such as `<external-root>/phase2`,
///    because the frontend intentionally persists `models/foo.gguf` paths.
///
/// When nothing exists the typed I/O error names every attempted location, so
/// the 400 tells the caller exactly where the server looked.
fn resolve_request_model_path(
    models_dir: &std::path::Path,
    requested: PathBuf,
) -> Result<PathBuf, BackendError> {
    if requested.is_absolute() || requested.exists() {
        return Ok(requested);
    }
    let mut attempted = vec![format!(
        "'{}' (relative to the server working directory)",
        requested.display()
    )];
    let joined = models_dir.join(&requested);
    if joined.exists() {
        return Ok(joined);
    }
    attempted.push(format!(
        "'{}' (under the configured models directory)",
        joined.display()
    ));
    if let Some(first) = requested.components().next() {
        let is_legacy_models_prefix = first.as_os_str() == std::ffi::OsStr::new("models");
        let is_models_dir_name = models_dir
            .file_name()
            .is_some_and(|dir_name| first.as_os_str() == dir_name);
        if is_legacy_models_prefix || is_models_dir_name {
            let stripped: PathBuf = requested.components().skip(1).collect();
            if !stripped.as_os_str().is_empty() {
                let candidate = models_dir.join(&stripped);
                if candidate.exists() {
                    return Ok(candidate);
                }
                attempted.push(format!(
                    "'{}' (under the configured models directory)",
                    candidate.display()
                ));
            }
        }
    }
    Err(BackendError::Io {
        path: requested,
        source: std::io::Error::new(
            std::io::ErrorKind::NotFound,
            format!("model file not found; tried {}", attempted.join(" and ")),
        ),
    })
}

fn resolve_lan_chat_model_path(
    models_dir: &std::path::Path,
    filename: Option<&str>,
) -> Result<PathBuf, &'static str> {
    let filename = filename.ok_or("select a model listed by this Camelid host")?;
    if !validate_local_model_filename(filename) {
        return Err("model selection must be one local GGUF filename");
    }
    let path = models_dir.join(filename);
    let metadata = std::fs::symlink_metadata(&path)
        .map_err(|_| "selected model is not present in the configured models directory")?;
    if metadata.file_type().is_symlink() || !metadata.is_file() {
        return Err(
            "selected model is not a direct regular file in the configured models directory",
        );
    }
    Ok(path)
}

#[cfg(test)]
mod models_dir_resolution_tests {
    use super::{resolve_lan_chat_model_path, resolve_models_dir, resolve_request_model_path};
    use crate::BackendError;
    use std::path::PathBuf;

    /// A models dir whose final component is literally `models`, holding one
    /// GGUF — the shipped/desktop layout the resolver's fallbacks target.
    fn models_dir_with(filename: &str) -> (tempfile::TempDir, PathBuf) {
        let tmp = tempfile::tempdir().expect("create tempdir");
        let models_dir = tmp.path().join("models");
        std::fs::create_dir(&models_dir).expect("create models dir");
        std::fs::write(models_dir.join(filename), b"gguf-stub").expect("write stub");
        (tmp, models_dir)
    }

    #[test]
    fn absolute_path_passes_through_even_when_missing() {
        let (_tmp, models_dir) = models_dir_with("present.gguf");
        let requested = if cfg!(windows) {
            PathBuf::from(r"C:\definitely\missing\model.gguf")
        } else {
            PathBuf::from("/definitely/missing/model.gguf")
        };
        let resolved = resolve_request_model_path(&models_dir, requested.clone())
            .expect("absolute paths are never rewritten");
        assert_eq!(resolved, requested);
    }

    #[test]
    fn relative_path_that_exists_in_cwd_stays_as_given() {
        // `cargo test` runs with the crate root as CWD, where Cargo.toml always
        // exists — the exact historical CWD-relative behavior must win even
        // though a models dir is configured.
        let (_tmp, models_dir) = models_dir_with("present.gguf");
        let resolved = resolve_request_model_path(&models_dir, PathBuf::from("Cargo.toml"))
            .expect("CWD-relative hit resolves");
        assert_eq!(resolved, PathBuf::from("Cargo.toml"));
    }

    #[test]
    fn relative_path_falls_back_to_the_configured_models_dir() {
        let name = "camelid-models-dir-resolution-test.gguf";
        let (_tmp, models_dir) = models_dir_with(name);
        let resolved = resolve_request_model_path(&models_dir, PathBuf::from(name))
            .expect("bare filename falls back to the models dir");
        assert_eq!(resolved, models_dir.join(name));
    }

    #[test]
    fn duplicated_models_component_is_stripped_against_the_models_dir() {
        // The live desktop repro: the client says "models/<file>" while the
        // configured dir already IS ".../models" — the duplicated leading
        // component is stripped rather than looking in ".../models/models/".
        let name = "camelid-models-dir-resolution-test.gguf";
        let (_tmp, models_dir) = models_dir_with(name);
        let resolved = resolve_request_model_path(&models_dir, PathBuf::from("models").join(name))
            .expect("models/-prefixed request resolves into the models dir");
        assert_eq!(resolved, models_dir.join(name));
    }

    #[test]
    fn legacy_models_prefix_is_stripped_for_a_custom_named_models_dir() {
        let tmp = tempfile::tempdir().expect("create tempdir");
        let models_dir = tmp.path().join("phase2");
        std::fs::create_dir(&models_dir).expect("create custom models dir");
        let name = "camelid-custom-models-dir-resolution-test.gguf";
        std::fs::write(models_dir.join(name), b"gguf-stub").expect("write stub");

        let resolved = resolve_request_model_path(&models_dir, PathBuf::from("models").join(name))
            .expect("legacy models/ prefix resolves inside a custom-named models dir");

        assert_eq!(resolved, models_dir.join(name));
    }

    #[test]
    fn missing_everywhere_error_names_every_attempted_location() {
        let (_tmp, models_dir) = models_dir_with("present.gguf");
        let requested = PathBuf::from("models").join("camelid-models-dir-missing.gguf");
        let err = resolve_request_model_path(&models_dir, requested.clone())
            .expect_err("nothing exists anywhere");
        assert!(matches!(err, BackendError::Io { .. }));
        let message = err.to_string();
        assert!(
            message.contains(&requested.display().to_string()),
            "error must name the CWD-relative attempt: {message}"
        );
        assert!(
            message.contains(&models_dir.join(&requested).display().to_string()),
            "error must name the models-dir attempt: {message}"
        );
        assert!(
            message.contains(
                &models_dir
                    .join("camelid-models-dir-missing.gguf")
                    .display()
                    .to_string()
            ),
            "error must name the stripped-component attempt: {message}"
        );
    }

    #[test]
    fn resolve_models_dir_is_absolute_for_default_and_relative_configs() {
        assert!(resolve_models_dir(None).is_absolute());
        assert!(resolve_models_dir(Some(PathBuf::from("models"))).is_absolute());
        let explicit = if cfg!(windows) {
            PathBuf::from(r"C:\somewhere\models")
        } else {
            PathBuf::from("/somewhere/models")
        };
        assert_eq!(resolve_models_dir(Some(explicit.clone())), explicit);
    }

    #[test]
    fn lan_chat_model_selection_accepts_only_a_direct_local_gguf() {
        let tmp = tempfile::tempdir().unwrap();
        let models_dir = tmp.path().join("models");
        std::fs::create_dir(&models_dir).unwrap();
        let model = models_dir.join("local.gguf");
        std::fs::write(&model, b"gguf-stub").unwrap();
        std::fs::write(models_dir.join("notes.txt"), b"not a model").unwrap();

        assert_eq!(
            resolve_lan_chat_model_path(&models_dir, Some("local.gguf")).unwrap(),
            model
        );
        for filename in [
            None,
            Some("../local.gguf"),
            Some("models/local.gguf"),
            Some("notes.txt"),
            Some("missing.gguf"),
        ] {
            assert!(
                resolve_lan_chat_model_path(&models_dir, filename).is_err(),
                "accepted {filename:?}"
            );
        }

        #[cfg(unix)]
        {
            std::os::unix::fs::symlink(&model, models_dir.join("linked.gguf")).unwrap();
            assert!(resolve_lan_chat_model_path(&models_dir, Some("linked.gguf")).is_err());
        }
        #[cfg(windows)]
        {
            if std::os::windows::fs::symlink_file(&model, models_dir.join("linked.gguf")).is_ok() {
                assert!(resolve_lan_chat_model_path(&models_dir, Some("linked.gguf")).is_err());
            }
        }
    }
}

pub fn router() -> Router {
    router_with_state(AppState::default())
}

#[cfg(test)]
pub(crate) fn router_with_workspace_cli_token_for_tests(token: &str) -> Router {
    router_with_state(AppState::default().with_workspace_cli_token(Some(token)))
}

pub fn router_with_state(state: AppState) -> Router {
    router_with_state_and_policy(state, server::ServerPolicy::loopback_default())
}

fn router_with_state_and_policy(state: AppState, policy: server::ServerPolicy) -> Router {
    let request_policy = policy.request_policy();
    let cors = policy.cors_layer();
    let body_limit = policy.limits.max_request_body_bytes;
    let metrics = state.metrics.clone();
    Router::new()
        .route("/health", get(health))
        .route("/v1/health", get(health))
        .route("/api/capabilities", get(capabilities))
        .route("/api/runtime/gpu", get(gpu_runtime).post(set_gpu_runtime))
        .route("/api/runtime/memory", get(runtime_memory))
        .route("/api/runtime/kv-cache/purge", post(purge_kv_cache))
        .route("/api/telemetry/stream", get(telemetry_stream))
        .route("/execution-plan", get(execution_plan))
        .route("/api/execution-plan", get(execution_plan))
        .route("/api/models/load", post(load_model))
        .route("/api/models/inspect", post(inspect_model))
        .route("/api/models/unload", post(unload_model))
        .route("/api/models/current", get(current_model))
        .route(
            "/api/models/verify",
            get(model_verification_status).post(verify_current_model),
        )
        .route("/api/models/metadata", get(model_metadata))
        .route("/api/models/tokenizer", get(model_tokenizer))
        .route("/api/models/tokenizer/encode", post(tokenizer_encode))
        .route("/api/models/tokenizer/decode", post(tokenizer_decode))
        .route("/tokenize", post(llama_server_tokenize))
        .route("/detokenize", post(llama_server_detokenize))
        .route("/apply-template", post(llama_server_apply_template))
        .route("/models", get(llama_server_models))
        .route("/models/load", post(llama_server_models_load))
        .route(
            "/models/unload",
            post(unsupported_llama_server_models_unload),
        )
        .route(
            "/props",
            get(llama_server_props).post(unsupported_llama_server_props),
        )
        .route(
            "/slots",
            get(llama_server_slots).post(unsupported_llama_server_slots),
        )
        .route("/metrics", get(metrics::prometheus))
        .route("/completion", post(llama_server_completion))
        .route("/infill", post(unsupported_llama_server_infill))
        .route("/embedding", post(embeddings))
        .route("/embeddings", post(embeddings))
        .route("/rerank", post(rerank))
        .route("/reranking", post(rerank))
        .route(
            "/api/generation/sessions",
            get(generation_sessions).post(create_generation_session),
        )
        .route("/api/generation/preflight", post(preflight_generation))
        .route("/api/web/research", post(web_research::handler))
        .route(
            "/api/agent/workspace/models",
            get(workspace::compatible_models),
        )
        .route("/api/agent/workspace/threads", get(workspace::list_threads))
        .route(
            "/api/agent/workspace/threads/:id",
            get(workspace::get_thread).delete(workspace::delete_thread),
        )
        .route(
            "/api/agent/workspace/threads/:id/compact",
            post(workspace::compact_thread).delete(workspace::undo_thread_compaction),
        )
        .route("/api/agent/workspace/browse", get(workspace::browse))
        .route(
            "/api/agent/workspace/sessions",
            post(workspace::create_session),
        )
        .route(
            "/api/agent/workspace/sessions/:id",
            get(workspace::session_status).delete(workspace::cancel_session),
        )
        .route(
            "/api/agent/workspace/sessions/:id/events",
            get(workspace::session_events),
        )
        .route(
            "/api/agent/workspace/sessions/:id/messages",
            post(workspace::send_message),
        )
        .route(
            "/api/agent/workspace/sessions/:id/decisions",
            post(workspace::decide),
        )
        .route("/api/models/local", get(local_models))
        .route("/api/models/local/delete", post(delete_local_model))
        .route(
            "/api/models/default",
            get(default_model).post(set_default_model),
        )
        .route("/api/models/runnable-receipt", get(runnable_receipt))
        .route("/api/models/runnable-smoke", post(run_runnable_smoke))
        .route("/api/models/catalog", get(get_catalog))
        .route("/api/models/catalog/fit", post(check_catalog_fit))
        .route("/api/models/catalog/install", post(install_catalog_model))
        .route("/api/models/catalog/downloads", get(get_catalog_downloads))
        .route("/api/models/catalog/cancel", post(cancel_catalog_download))
        .route(
            "/api/models/catalog/ack",
            post(acknowledge_catalog_download),
        )
        .route("/v1/models", get(v1_models))
        .route("/v1/models/:model", get(v1_model))
        .route("/v1/completions", post(completions))
        .route("/v1/chat/completions", post(chat_completions))
        .route("/v1/embeddings", post(embeddings))
        .route("/v1/responses", post(responses::create))
        .route(
            "/v1/responses/:id",
            get(responses::get_response).delete(responses::delete_response),
        )
        .route("/v1/conversations", post(responses::create_conversation))
        .route(
            "/v1/conversations/:id",
            get(responses::get_conversation)
                .post(responses::update_conversation)
                .delete(responses::delete_conversation),
        )
        .route(
            "/v1/conversations/:id/items",
            get(responses::list_conversation_items).post(responses::add_conversation_items),
        )
        .route(
            "/v1/conversations/:id/items/:item_id",
            get(responses::get_conversation_item).delete(responses::delete_conversation_item),
        )
        .route("/v1/messages", post(unsupported_messages))
        .route("/v1/rerank", post(rerank))
        .route("/v1/reranking", post(rerank))
        // Anything not matched above is served from the embedded web UI (the
        // chat surface and its static assets), with a client-side-route
        // fallback to the app shell. API routes are matched first.
        .fallback(crate::web_ui::handler)
        .layer(DefaultBodyLimit::max(body_limit))
        .layer(middleware::from_fn_with_state(
            request_policy,
            server::authenticate,
        ))
        .layer(middleware::from_fn_with_state(
            metrics,
            metrics::observe_http,
        ))
        .layer(cors)
        .layer(TraceLayer::new_for_http())
        .with_state(state)
}

/// The model `serve` loads at startup, and where that choice came from.
///
/// The origin decides what a load failure means. A path the user named on the
/// command line is a request, so failing it loudly with a non-zero exit is the
/// honest answer. A path Camelid picked out of the models directory for itself
/// is a convenience, and one unreadable file there must not cost the user the
/// whole server — the UI they would use to pick another model is served by the
/// very process that failure would take down.
pub struct StartupModel {
    pub path: PathBuf,
    /// `true` when the path came from `--model`.
    pub explicit: bool,
    distributed_model_sha256: Option<String>,
}

impl StartupModel {
    /// A model the user named; a load failure is fatal.
    pub fn explicit(path: PathBuf) -> Self {
        Self {
            path,
            explicit: true,
            distributed_model_sha256: None,
        }
    }

    pub fn distributed(path: PathBuf, model_sha256: String) -> Self {
        Self {
            path,
            explicit: true,
            distributed_model_sha256: Some(model_sha256),
        }
    }

    /// A model Camelid chose from the models directory; a load failure is not.
    pub fn auto_selected(path: PathBuf) -> Self {
        Self {
            path,
            explicit: false,
            distributed_model_sha256: None,
        }
    }
}

pub async fn serve(
    addr: SocketAddr,
    configured_threads: Option<usize>,
    initial_model: Option<StartupModel>,
    open_ui: bool,
    default_enable_thinking: bool,
    models_dir: Option<PathBuf>,
    options: ServeOptions,
) -> std::io::Result<()> {
    let policy = server::ServerPolicy::resolve(addr, options)?;
    let std_listener = std::net::TcpListener::bind(addr)?;
    std_listener.set_nonblocking(true)?;
    let mut state = AppState::with_configured_threads(configured_threads)
        .with_default_enable_thinking(default_enable_thinking)
        .with_local_model_delete(addr.ip().is_loopback())
        .with_models_dir(models_dir)
        .with_serve_addr(addr)
        .with_server_policy(&policy);
    state.distributed_model_sha256 = initial_model
        .as_ref()
        .and_then(|model| model.distributed_model_sha256.clone());
    let workspace_cli_credential = if addr.ip().is_loopback() {
        match crate::workspace_auth::WorkspaceCliCredential::issue(addr) {
            Ok(credential) => Some(credential),
            Err(error) => {
                tracing::warn!(%error, "Workspace CLI authentication is unavailable");
                eprintln!(
                    "  Workspace CLI unavailable: could not create its local credential ({error})"
                );
                None
            }
        }
    } else {
        None
    };
    state = state.with_workspace_cli_token(
        workspace_cli_credential
            .as_ref()
            .map(crate::workspace_auth::WorkspaceCliCredential::token),
    );
    tracing::info!(
        %addr,
        auth_enabled = policy.auth.enabled(),
        tls_enabled = policy.tls.is_some(),
        cors_origin_count = policy.cors_origin_count(),
        max_request_body_bytes = policy.limits.max_request_body_bytes,
        max_prompt_tokens = policy.limits.max_prompt_tokens,
        max_generation_tokens = policy.limits.max_generation_tokens,
        max_download_bytes = policy.limits.max_download_bytes,
        remote_unauthenticated_override = policy.remote_unauthenticated_override,
        "camelid server policy resolved"
    );
    let scheme = if policy.tls.is_some() {
        "https"
    } else {
        "http"
    };
    let url = format!("{scheme}://{addr}");

    // Warm the model-fit dimension cache in the background: header-only reads
    // (never weights), disk-cached across restarts, de-duplicated, and globally
    // rate-limited. This is why catalog fit badges can be *exact* without any
    // per-request fetching. Best-effort; opt out with CAMELID_NO_REMOTE_DIMS=1.
    crate::fit_dims::start_background(
        curated_catalog()
            .iter()
            .map(|c| (c.repo_id.to_string(), c.filename.to_string(), c.size_bytes))
            .collect(),
    );

    // The router owns `state`; the startup load below shares the same Arcs, so
    // a model it loads is visible to every request the listener is already
    // answering.
    let startup_state = state.clone();
    let app = router_with_state_and_policy(state, policy.clone());
    let tls_enabled = policy.tls.is_some();
    let server = if let Some(tls) = &policy.tls {
        let tls_config = axum_server::tls_rustls::RustlsConfig::from_pem_file(&tls.cert, &tls.key)
            .await
            .map_err(|error| {
                std::io::Error::new(
                    std::io::ErrorKind::InvalidInput,
                    format!("could not load TLS certificate/key: {error}"),
                )
            })?;
        let server = axum_server::from_tcp_rustls(std_listener, tls_config)?;
        tokio::spawn(async move {
            server
                .serve(app.into_make_service())
                .await
                .map_err(std::io::Error::other)
        })
    } else {
        let listener = tokio::net::TcpListener::from_std(std_listener)?;
        tokio::spawn(async move { axum::serve(listener, app).await })
    };
    // Load the startup model AFTER the listener is accepting, so /health and
    // /api/capabilities answer throughout the load. The desktop supervisor
    // kills the sidecar when its health poll goes unanswered for 40s, and a
    // large startup model (auto-selected whenever the models dir is populated)
    // used to keep the port closed for the entire load — a healthy engine
    // looked dead exactly when it had the most work to do.
    //
    // A model the user NAMED still exits with the same message and non-zero
    // status. A model Camelid auto-selected does not: the pick is made by
    // filename order over whatever sits in the models directory, so a single
    // unreadable file there (an interrupted `pull` leaves a short .gguf under
    // the final name, and `curl -C -` needs it to stay there to resume) would
    // otherwise take down the server on every launch, including the UI the
    // user needs to choose a different model. Reinstalling does not help —
    // the models directory outlives the app — so the failure is permanent.
    if let Some(StartupModel { path, explicit, .. }) = initial_model {
        if let Err(err) = load_model_from_path(&startup_state, path.clone(), None, true).await {
            tracing::error!(error=%err, "failed to load startup model");
            if explicit {
                eprintln!("\n  Could not load that model: {err}");
                eprintln!("  Camelid serves specific validated Q8_0 rows. To get one:");
                eprintln!("      camelid pull            # list supported models");
                eprintln!("      camelid pull <id>       # download one into ./models\n");
                return Err(std::io::Error::other(err.to_string()));
            }
            eprintln!("\n  Could not load {}: {err}", path.display());
            eprintln!(
                "  Camelid picked that file automatically from {}.",
                startup_state.models_dir.display()
            );
            eprintln!("  The server is still running. Open the UI to choose another model,");
            eprintln!("  or delete that file if it is a broken download and fetch it again.\n");
        }
    }
    // Warm the generation path BEFORE telling the user we're ready. The GPU resident
    // engine (NVRTC kernel compile + multi-GB weight upload + first prefill) is built
    // lazily on the first generation â€” a one-time cost of several seconds. If it lands
    // on the user's first prompt the model looks "dog slow" (it's really the cold
    // build, on the GPU the whole time). So: start serving in the background, fire one
    // tiny self-request through the exact same code path to build the engine, BLOCK on
    // it, and only then print "ready". After this the first real request is warm
    // (~0.5s) instead of ~10s. The warm-up is best-effort â€” any failure just falls back
    // to the old lazy build and is not fatal.
    let warm_model_id = startup_state.active_model_id.read().await.clone();
    if let Some(model_id) = warm_model_id {
        // Word the banner for the device that will actually serve â€” saying "GPU"
        // on a CPU-only run (e.g. CUDA_VISIBLE_DEVICES=-1) was misleading.
        let warming_msg = if crate::cuda::gpu_accel_enabled() {
            "ðŸª Warming up the GPU (building the resident engine, one-time)â€¦"
        } else {
            "ðŸª Warming up the model (building the engine, one-time)â€¦"
        };
        eprintln!("\n  {warming_msg}");
        if tls_enabled {
            tracing::info!("skipping HTTP self-warmup because TLS is enabled");
        } else if startup_state
            .gemma4_serve_lanes
            .read()
            .await
            .get(&model_id)
            .is_some_and(|lane| *lane == Gemma4ServeLane::GhostMoe)
        {
            // A normal resident runtime benefits from paying its one-token
            // initialization cost before the UI appears. Ghost-MoE is already
            // initialized at load and a one-token chat would instead page a
            // full prompt through hundreds of expert records, delaying the UI
            // by minutes and competing with the user's first request.
            tracing::info!("skipping generation warm-up for disk-paged Gemma 4 Ghost-MoE");
            eprintln!("  Ghost-MoE runtime ready; skipping resident-engine warm-up");
        } else {
            warmup_generation_blocking(addr, model_id, policy.auth.bearer_header_line()).await;
        }
    }
    print_ready_banner(&url);
    if workspace_cli_credential.is_some() {
        eprintln!("  Workspace CLI: ready");
    }
    if open_ui {
        crate::web_ui::open_in_browser(&url);
    }
    server.await.map_err(std::io::Error::other)?
}

#[cfg(test)]
mod startup_model_tests {
    use super::*;
    use std::io::{Read, Write};
    use std::net::TcpStream;

    /// A GGUF by file extension only — what an interrupted download leaves
    /// behind, and what any corrupt or unsupported file looks like to the
    /// loader. Every load path rejects it.
    fn unloadable_gguf(dir: &std::path::Path) -> PathBuf {
        let path = dir.join("broken.gguf");
        std::fs::write(&path, b"not a gguf").expect("write broken gguf");
        path
    }

    /// Reserve a loopback port and return its address; the listener is dropped
    /// so `serve` can bind it.
    fn reserved_loopback_addr() -> SocketAddr {
        let listener =
            std::net::TcpListener::bind("127.0.0.1:0").expect("bind loopback ephemeral port");
        listener.local_addr().expect("read reserved port")
    }

    /// The desktop supervisor's own gate, byte for byte: a loopback GET of
    /// `/v1/health` that counts only a 200.
    fn health_ok(addr: SocketAddr) -> bool {
        let Ok(mut stream) = TcpStream::connect_timeout(&addr, Duration::from_millis(500)) else {
            return false;
        };
        let _ = stream.set_read_timeout(Some(Duration::from_secs(2)));
        let request =
            format!("GET /v1/health HTTP/1.1\r\nHost: {addr}\r\nConnection: close\r\n\r\n");
        if stream.write_all(request.as_bytes()).is_err() {
            return false;
        }
        let mut buf = [0u8; 64];
        matches!(stream.read(&mut buf), Ok(read) if read > 0
            && String::from_utf8_lossy(&buf[..read]).starts_with("HTTP/1.1 200"))
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn an_auto_selected_startup_model_that_cannot_load_keeps_the_server_up() {
        let dir = tempfile::tempdir().expect("temp models dir");
        let broken = unloadable_gguf(dir.path());
        let addr = reserved_loopback_addr();

        let server = tokio::spawn(serve(
            addr,
            None,
            Some(StartupModel::auto_selected(broken)),
            false,
            false,
            Some(dir.path().to_path_buf()),
            ServeOptions::default(),
        ));

        // Camelid picked the file itself, so it owes the user a running server
        // and the UI to choose again — not an exit that reinstalling can't fix,
        // because the models directory outlives the app.
        //
        // Two failure modes, asserted separately. The contract this test guards is that the
        // serve task STAYS ALIVE; reaching /v1/health is how we confirm it is really serving.
        // Collapsing both into one `healthy` flag made a slow runner indistinguishable from a
        // genuine regression — the old form polled a fixed 100 × 100 ms and failed CI with
        // "must not take the server down" even when the server was up and merely slow to bind.
        // The wait is now deadline-based and generous; it costs nothing in the passing case
        // because the loop exits the moment health answers.
        let deadline = std::time::Instant::now() + Duration::from_secs(60);
        let mut healthy = false;
        let mut exited_early = false;
        while std::time::Instant::now() < deadline {
            if server.is_finished() {
                exited_early = true;
                break;
            }
            if tokio::task::spawn_blocking(move || health_ok(addr))
                .await
                .unwrap_or(false)
            {
                healthy = true;
                break;
            }
            tokio::time::sleep(Duration::from_millis(100)).await;
        }
        server.abort();

        assert!(
            !exited_early,
            "an auto-selected startup model that cannot load must not take the server down, \
             but the serve task exited on its own"
        );
        assert!(
            healthy,
            "the serve task stayed alive but never answered /v1/health within 60s — the \
             startup-model contract held, so suspect a slow or loaded runner rather than a \
             regression in it"
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn an_explicitly_named_startup_model_that_cannot_load_still_fails_the_run() {
        let dir = tempfile::tempdir().expect("temp models dir");
        let broken = unloadable_gguf(dir.path());
        let addr = reserved_loopback_addr();

        // `--model` is a request, not a guess, so it keeps failing loudly.
        let result = serve(
            addr,
            None,
            Some(StartupModel::explicit(broken)),
            false,
            false,
            Some(dir.path().to_path_buf()),
            ServeOptions::default(),
        )
        .await;

        assert!(
            result.is_err(),
            "an explicitly named model that cannot load must fail the run"
        );
    }
}

/// One-shot self-request to build/warm the generation engine, awaited so startup
/// blocks until the GPU resident engine is built (kernels compiled, weights uploaded,
/// first prefill run). Runs the blocking `std::net` round-trip on the blocking pool so
/// the spawned server task can answer it concurrently. Best-effort: any failure (or
/// the 180s safety timeout) just returns, leaving the old lazy-build behaviour.
async fn warmup_generation_blocking(
    addr: SocketAddr,
    model_id: String,
    auth_header: Option<String>,
) {
    let _ = tokio::task::spawn_blocking(move || {
        warmup_request(addr, &model_id, auth_header.as_deref())
    })
    .await;
}

/// Send the warm-up chat request and read the full response (blocking). Returns once
/// the forward has completed so the resident engine is built before the caller
/// proceeds. Errors are swallowed by the caller â€” this only shaves the cold start.
fn warmup_request(addr: SocketAddr, model_id: &str, auth_header: Option<&str>) {
    let text_body = serde_json::json!({
        "model": model_id,
        "messages": [{ "role": "user", "content": "hi" }],
        "max_tokens": 1,
        "temperature": 0,
        "stream": false,
    })
    .to_string();
    warmup_http_post(addr, auth_header, &text_body);

    // The ordinary one-token warm-up does not touch the multimodal projector or
    // the wide Q1 prompt kernels. When a Bonsai-27B projector is present that
    // leaves NVRTC/driver JIT and its VRAM-aware matrix cache on the user's first
    // image. Run one generated 224x224 PNG through the real API before announcing
    // readiness. If no projector is installed the typed API rejection is harmless.
    let id = model_id.to_ascii_lowercase();
    if id.contains("bonsai") && id.contains("27b") {
        use image::ImageEncoder as _;
        let pixels = vec![0u8; 224 * 224 * 3];
        let mut png = Vec::new();
        let encoded = image::codecs::png::PngEncoder::new(&mut png).write_image(
            &pixels,
            224,
            224,
            image::ExtendedColorType::Rgb8,
        );
        if encoded.is_ok() {
            let url = format!("data:image/png;base64,{}", BASE64_STANDARD.encode(&png));
            let vision_body = serde_json::json!({
                "model": model_id,
                "messages": [{
                    "role": "user",
                    "content": [
                        { "type": "text", "text": "Describe the image briefly." },
                        { "type": "image_url", "image_url": { "url": url } }
                    ]
                }],
                "max_tokens": 2,
                "temperature": 0,
                "stream": false,
                "camelid_enable_thinking": false,
            })
            .to_string();
            warmup_http_post(addr, auth_header, &vision_body);
        }
    }
}

fn warmup_http_post(addr: SocketAddr, auth_header: Option<&str>, body: &str) {
    use std::io::{Read, Write};
    // Give the just-spawned listener a moment to start accepting; retry briefly.
    let mut stream = None;
    for _ in 0..40 {
        match std::net::TcpStream::connect(addr) {
            Ok(s) => {
                stream = Some(s);
                break;
            }
            Err(_) => std::thread::sleep(Duration::from_millis(50)),
        }
    }
    let Some(mut stream) = stream else {
        return;
    };
    // Don't let a stuck forward hang startup forever.
    let _ = stream.set_read_timeout(Some(Duration::from_secs(180)));
    let auth_header = auth_header.unwrap_or("");
    let request = format!(
        "POST /v1/chat/completions HTTP/1.1\r\nHost: {addr}\r\n{auth_header}Content-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
        body.len(),
        body,
    );
    if stream.write_all(request.as_bytes()).is_ok() {
        let mut sink = Vec::new();
        let _ = stream.read_to_end(&mut sink);
        tracing::info!("generation warm-up complete");
    }
}

/// Print a clear, human-facing pointer to the web UI once the server is up.
/// `tracing` output is for operators; this banner is for the person who just
/// ran `camelid serve` and wants to know where to click.
fn print_ready_banner(url: &str) {
    eprintln!("\n  ðŸª Camelid is ready");
    eprintln!("  Open the chat UI:  {url}");
    eprintln!("  OpenAI-style API:  {url}/v1/chat/completions\n");
}

/// Live inference telemetry stream (SSE). Subscribers receive only events
/// emitted by real inference work (see `crate::telemetry`); an idle server
/// sends nothing beyond the initial hello and keep-alive comments.
async fn telemetry_stream() -> Response {
    let mut rx = telemetry::hub().subscribe();
    let events = async_stream::stream! {
        let hello = serde_json::json!({
            "event": "hello",
            "schema": telemetry::TELEMETRY_SCHEMA,
            "engine": "camelid",
        });
        yield Ok::<Event, Infallible>(Event::default().event("telemetry").data(hello.to_string()));
        loop {
            match rx.recv().await {
                Ok(envelope) => match serde_json::to_string(&envelope) {
                    Ok(json) => yield Ok(Event::default().event("telemetry").data(json)),
                    Err(_) => continue,
                },
                Err(tokio::sync::broadcast::error::RecvError::Lagged(skipped)) => {
                    let notice = serde_json::json!({ "event": "lagged", "skipped": skipped });
                    yield Ok(Event::default().event("telemetry").data(notice.to_string()));
                }
                Err(tokio::sync::broadcast::error::RecvError::Closed) => break,
            }
        }
    };
    Sse::new(events)
        .keep_alive(
            axum::response::sse::KeepAlive::new()
                .interval(Duration::from_secs(10))
                .text("ping"),
        )
        .into_response()
}

/// Upper bound on how long the liveness endpoints (`/health`, `/v1/health`,
/// `/api/capabilities`) may wait on the shared model registries.
///
/// These endpoints gate external supervision — the desktop app kills the
/// sidecar when a health poll goes unanswered for its 40s startup window — so
/// a model load/unload mutating the registries must never make them
/// unresponsive. The registry locks are fair: once a load's write is queued,
/// new readers park behind it, so an unbounded `read().await` here inherits
/// the full latency of whatever the writer is stuck on. On timeout the
/// endpoints answer from lock-free state instead of parking.
const LIVENESS_LOCK_BUDGET: Duration = Duration::from_millis(500);

async fn health(State(state): State<AppState>) -> Json<HealthResponse> {
    match tokio::time::timeout(LIVENESS_LOCK_BUDGET, health_registry_snapshot(&state)).await {
        Ok(response) => Json(response),
        // A model transition is holding the registries: answer from lock-free
        // state rather than queueing behind the writer. `ok` stays true — the
        // process is alive and serving; the registry-derived fields report
        // not-ready, which the next poll refreshes once the transition ends.
        Err(_busy) => Json(busy_health_response(&state)),
    }
}

fn active_gemma4_serve_lane(
    active_model_id: Option<&str>,
    lanes: &HashMap<String, Gemma4ServeLane>,
) -> Option<Gemma4ServeLane> {
    active_model_id.and_then(|id| lanes.get(id).copied())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Gemma4GhostExecutionHealth {
    mode: Gemma4GhostExecutionMode,
    backend: Gemma4GhostBackend,
    common_gpu_active: bool,
    experts_gpu_active: bool,
    head_gpu_active: bool,
    common_metal_active: bool,
    experts_metal_active: bool,
    head_metal_active: bool,
}

fn gemma4_ghost_execution_health(
    lane: Option<Gemma4ServeLane>,
    runtime_present: bool,
    metal: crate::gemma4_runtime::Gemma4GhostMetalComponents,
    cuda: crate::gemma4_runtime::Gemma4GhostCudaComponents,
    gpu_enabled: bool,
    deterministic: bool,
) -> Option<Gemma4GhostExecutionHealth> {
    if lane != Some(Gemma4ServeLane::GhostMoe) || !runtime_present {
        return None;
    }
    let gpu_allowed = gpu_enabled && !deterministic;
    let cuda_active = gpu_allowed && (cuda.common || cuda.experts || cuda.head);
    let metal_active = gpu_allowed && (metal.common || metal.experts || metal.head);
    let (backend, common_gpu_active, experts_gpu_active, head_gpu_active, mode) = if cuda_active {
        let mode = if cuda.common {
            Gemma4GhostExecutionMode::FullCommonCuda
        } else {
            Gemma4GhostExecutionMode::HybridCuda
        };
        (
            Gemma4GhostBackend::Cuda,
            cuda.common,
            cuda.experts,
            cuda.head,
            mode,
        )
    } else if metal_active {
        let mode = if metal.common {
            Gemma4GhostExecutionMode::FullCommonMetal
        } else {
            Gemma4GhostExecutionMode::HybridMetal
        };
        (
            Gemma4GhostBackend::Metal,
            metal.common,
            metal.experts,
            metal.head,
            mode,
        )
    } else {
        (
            Gemma4GhostBackend::Cpu,
            false,
            false,
            false,
            Gemma4GhostExecutionMode::CpuStorage,
        )
    };
    Some(Gemma4GhostExecutionHealth {
        mode,
        backend,
        common_gpu_active,
        experts_gpu_active,
        head_gpu_active,
        common_metal_active: metal_active && metal.common,
        experts_metal_active: metal_active && metal.experts,
        head_metal_active: metal_active && metal.head,
    })
}

async fn health_registry_snapshot(state: &AppState) -> HealthResponse {
    let active_id_lock = state.active_model_id.read().await;
    let loaded_models = state.loaded_models.read().await;
    let model = active_id_lock.as_ref().and_then(|id| loaded_models.get(id));
    let loaded_now = !loaded_models.is_empty();
    // Is the active model served by a gemma4 runtime?
    let gemma4_runtime = match active_id_lock.as_ref() {
        Some(id) => state.gemma4_runtimes.read().await.get(id).cloned(),
        None => None,
    };
    let gemma4_available = gemma4_runtime.is_some();
    let model_family = model.map(|m| model_family(&m.gguf));
    // Specialized serve lanes are ready only when their active runtime instance exists.
    // Model load inserts the generic metadata before initializing these runtimes, and a
    // failed initialization leaves the model visible but intentionally not ready. Health
    // must agree with request routing, which also requires the runtime-map entry.
    let runnable_runtime = match active_id_lock.as_ref() {
        Some(id) => state.runnable_runtimes.read().await.get(id).cloned(),
        None => None,
    };
    let runnable_serve_ready = runnable_runtime.is_some();
    let vision_ready = runnable_runtime
        .as_ref()
        .is_some_and(|runtime| runtime.vision_ready());
    let dg_serve_ready = match active_id_lock.as_ref() {
        Some(id) => state.dg_runtimes.read().await.contains_key(id),
        None => false,
    };
    let backend = health_backend(
        gemma4_available,
        runnable_serve_ready,
        dg_serve_ready,
        model.is_some(),
    );
    let generation_ready = gemma4_available
        || runnable_serve_ready
        || dg_serve_ready
        || model.is_some_and(loaded_model_generation_ready);
    let active_context_length = model
        .and_then(|model| model.llama_config.as_ref())
        .map(|config| config.context_length);
    let execution_plans = state.execution_plans.read().await;
    let execution_plan = active_id_lock
        .as_ref()
        .and_then(|id| execution_plans.get(id))
        .cloned();
    let gemma4_serve_lanes = state.gemma4_serve_lanes.read().await;
    let gemma4_serve_lane = if gemma4_available {
        active_gemma4_serve_lane(active_id_lock.as_deref(), &gemma4_serve_lanes)
    } else {
        None
    };
    let ghost_catalog_managed = if gemma4_serve_lane == Some(Gemma4ServeLane::GhostMoe) {
        let managed = state.gemma4_catalog_managed_ghosts.read().await;
        Some(
            active_id_lock
                .as_ref()
                .and_then(|id| managed.get(id).copied())
                .unwrap_or(false),
        )
    } else {
        None
    };
    // Ask the active runtime, rather than the generic execution plan, which
    // exact Ghost accelerator components still exist. These snapshots never
    // take the stateful CUDA generation lock. Then apply both live dispatch
    // gates so POST /api/runtime/gpu and deterministic mode are reflected on
    // the very next health poll without a model reload.
    let metal_constructed = gemma4_runtime
        .as_deref()
        .map(Gemma4ServeRuntime::ghost_metal_components_constructed)
        .unwrap_or_default();
    let cuda_constructed = gemma4_runtime
        .as_deref()
        .map(Gemma4ServeRuntime::ghost_cuda_components_constructed)
        .unwrap_or_default();
    let ghost_execution = gemma4_ghost_execution_health(
        gemma4_serve_lane,
        gemma4_runtime.is_some(),
        metal_constructed,
        cuda_constructed,
        crate::cuda::gpu_accel_enabled(),
        crate::inference::deterministic_mode_enabled(),
    );
    let slot = state.engine.slot_snapshot();
    HealthResponse {
        ok: true,
        engine: "camelid",
        api_surface: state.api_surface,
        version: env!("CARGO_PKG_VERSION"),
        build: crate::receipt::camelid_version(),
        loaded_now,
        generation_ready,
        active_context_length,
        max_prompt_tokens: state.server_limits.max_prompt_tokens,
        max_generation_tokens: state.server_limits.max_generation_tokens,
        vision_ready,
        active_model_id: active_id_lock.clone(),
        q8_runtime: q8_runtime_health(),
        execution_plan,
        backend,
        model_family,
        gemma4_available,
        gemma4_serve_lane,
        gemma4_ghost_common_metal_active: ghost_execution.map(|health| health.common_metal_active),
        gemma4_ghost_execution_mode: ghost_execution.map(|health| health.mode),
        gemma4_ghost_experts_metal_active: ghost_execution
            .map(|health| health.experts_metal_active),
        gemma4_ghost_head_metal_active: ghost_execution.map(|health| health.head_metal_active),
        gemma4_ghost_backend: ghost_execution.map(|health| health.backend),
        gemma4_ghost_catalog_managed: ghost_catalog_managed,
        gemma4_ghost_common_gpu_active: ghost_execution.map(|health| health.common_gpu_active),
        gemma4_ghost_experts_gpu_active: ghost_execution.map(|health| health.experts_gpu_active),
        gemma4_ghost_head_gpu_active: ghost_execution.map(|health| health.head_gpu_active),
        engine_queue_depth: state.engine.depth(),
        engine_queued_tasks: slot.queued_tasks,
        engine_active_task_id: slot.active_task_id,
        engine_active_generated_tokens: slot.completed_units,
        engine_active_elapsed_seconds: slot.active_elapsed_seconds,
        engine_stalled_seconds: slot.stalled_seconds,
        continuous_batch_slots: state.engine.continuous_batch_slots(),
        executable: discloses_host_details(state.serve_addr, state.api_surface)
            .then(|| loopback_executable_path(state.serve_addr))
            .flatten(),
        listen_addr: discloses_host_details(state.serve_addr, state.api_surface)
            .then(|| state.serve_addr.to_string()),
    }
}

#[derive(Debug)]
struct KvCacheEntryMemory {
    model_id: String,
    bytes: u64,
    tokens: usize,
}

fn kv_cache_memory_snapshot(state: &AppState) -> (Vec<KvCacheEntryMemory>, usize) {
    let Ok(pool) = state.cached_prompt_prefix.lock() else {
        return (Vec::new(), 0);
    };
    let entries = pool
        .entries
        .iter()
        .map(|entry| KvCacheEntryMemory {
            model_id: entry.cached.model_id.clone(),
            bytes: entry.cached.session.kv_cache_allocated_bytes(),
            tokens: entry.cached.token_ids.len(),
        })
        .collect();
    (entries, pool.capacity)
}

async fn runtime_memory(State(state): State<AppState>) -> Json<RuntimeMemoryResponse> {
    let (kv_entries, kv_cache_capacity) = kv_cache_memory_snapshot(&state);
    let kv_cache_bytes = kv_entries.iter().map(|entry| entry.bytes).sum();
    let active_model_id = state.active_model_id.read().await.clone();
    let loaded_models = state.loaded_models.read().await;
    let mut models = loaded_models
        .values()
        .map(|model| {
            let model_cache: Vec<_> = kv_entries
                .iter()
                .filter(|entry| entry.model_id == model.id)
                .collect();
            RuntimeModelMemory {
                id: model.id.clone(),
                active: active_model_id.as_ref() == Some(&model.id),
                weight_bytes_estimate: std::fs::metadata(&model.path)
                    .map(|metadata| metadata.len())
                    .unwrap_or(0),
                kv_cache_bytes: model_cache.iter().map(|entry| entry.bytes).sum(),
                kv_cache_entries: model_cache.len(),
                cached_tokens: model_cache.iter().map(|entry| entry.tokens).sum(),
            }
        })
        .collect::<Vec<_>>();
    models.sort_by(|left, right| left.id.cmp(&right.id));
    let model_weight_bytes_estimate = models.iter().map(|model| model.weight_bytes_estimate).sum();

    Json(RuntimeMemoryResponse {
        process_resident_bytes: metrics::current_process_rss_bytes(),
        model_weight_bytes_estimate,
        kv_cache_bytes,
        kv_cache_entries: kv_entries.len(),
        kv_cache_capacity,
        models,
    })
}

async fn purge_kv_cache(State(state): State<AppState>) -> Json<PurgeKvCacheResponse> {
    let (entries, _) = kv_cache_memory_snapshot(&state);
    let released_bytes_estimate = entries.iter().map(|entry| entry.bytes).sum();
    let purged_entries = entries.len();
    clear_prompt_prefix_cache(&state);
    Json(PurgeKvCacheResponse {
        purged_entries,
        released_bytes_estimate,
    })
}

/// `/health` while a model transition holds the registries: every field that
/// would need a registry lock reports the in-flux state as not-ready; the
/// engine gauges, Q8 policy, and listener identity are lock-free and stay
/// live. The process is alive and serving, so `ok` remains true.
fn busy_health_response(state: &AppState) -> HealthResponse {
    let slot = state.engine.slot_snapshot();
    HealthResponse {
        ok: true,
        engine: "camelid",
        api_surface: state.api_surface,
        version: env!("CARGO_PKG_VERSION"),
        build: crate::receipt::camelid_version(),
        loaded_now: false,
        generation_ready: false,
        active_context_length: None,
        max_prompt_tokens: state.server_limits.max_prompt_tokens,
        max_generation_tokens: state.server_limits.max_generation_tokens,
        vision_ready: false,
        active_model_id: None,
        q8_runtime: q8_runtime_health(),
        execution_plan: None,
        backend: health_backend(false, false, false, false),
        model_family: None,
        gemma4_available: false,
        gemma4_serve_lane: None,
        gemma4_ghost_common_metal_active: None,
        gemma4_ghost_execution_mode: None,
        gemma4_ghost_experts_metal_active: None,
        gemma4_ghost_head_metal_active: None,
        gemma4_ghost_backend: None,
        gemma4_ghost_catalog_managed: None,
        gemma4_ghost_common_gpu_active: None,
        gemma4_ghost_experts_gpu_active: None,
        gemma4_ghost_head_gpu_active: None,
        engine_queue_depth: state.engine.depth(),
        engine_queued_tasks: slot.queued_tasks,
        engine_active_task_id: slot.active_task_id,
        engine_active_generated_tokens: slot.completed_units,
        engine_active_elapsed_seconds: slot.active_elapsed_seconds,
        engine_stalled_seconds: slot.stalled_seconds,
        continuous_batch_slots: state.engine.continuous_batch_slots(),
        executable: discloses_host_details(state.serve_addr, state.api_surface)
            .then(|| loopback_executable_path(state.serve_addr))
            .flatten(),
        listen_addr: discloses_host_details(state.serve_addr, state.api_surface)
            .then(|| state.serve_addr.to_string()),
    }
}

/// Whether the public health route may name this machine. Pure.
///
/// A loopback bind used to mean the reader is sitting at the keyboard.
/// `--lan-chat-only` exists to serve a remote browser, and reaching it through
/// a tunnel or a reverse proxy leaves the listener on loopback, so the surface
/// has to be consulted as well as the address.
fn discloses_host_details(serve_addr: SocketAddr, api_surface: ApiSurface) -> bool {
    serve_addr.ip().is_loopback() && matches!(api_surface, ApiSurface::Full)
}

/// Resolve the running binary's path for [`HealthResponse::executable`].
///
/// Returns `None` for any non-loopback listener so a remotely reachable server
/// never discloses its filesystem layout, and `None` when the path cannot be
/// determined — the caller treats absence as "fall back to generic advice".
fn loopback_executable_path(serve_addr: SocketAddr) -> Option<String> {
    if !serve_addr.ip().is_loopback() {
        return None;
    }
    let path = std::env::current_exe().ok()?;
    let path = path.to_string_lossy().into_owned();
    // Strip the Windows verbatim prefix if one is present: `\\?\C:\...` is valid
    // for the OS but is not something a user can paste into a shell.
    Some(path.strip_prefix(r"\\?\").unwrap_or(&path).to_string())
}

#[cfg(test)]
mod executable_disclosure_tests {
    use super::{discloses_host_details, loopback_executable_path, ApiSurface};
    use std::net::SocketAddr;

    #[test]
    fn a_loopback_listener_reports_the_running_binary() {
        for addr in ["127.0.0.1:8181", "[::1]:8181"] {
            let resolved = loopback_executable_path(addr.parse::<SocketAddr>().unwrap())
                .expect("a loopback listener discloses its own path");
            assert!(
                !resolved.starts_with(r"\\?\"),
                "the verbatim prefix is not shell-pasteable: {resolved}"
            );
            // The test binary is what is running, so this is the honest answer.
            assert!(
                std::path::Path::new(&resolved).exists(),
                "reported a path that does not exist: {resolved}"
            );
        }
    }

    #[test]
    fn a_reachable_listener_discloses_nothing() {
        // The path usually contains a username, and the advice would be useless
        // to a reader who is not sitting at this machine anyway.
        for addr in ["0.0.0.0:8181", "192.0.2.10:8181"] {
            assert_eq!(
                loopback_executable_path(addr.parse::<SocketAddr>().unwrap()),
                None,
                "{addr} must not disclose the binary path"
            );
        }
    }

    /// A LAN Chat listener is read by a phone, and it stays on loopback when it
    /// is reached through a tunnel, so the address alone cannot answer this.
    #[test]
    fn a_lan_chat_listener_names_this_machine_to_nobody() {
        let loopback: SocketAddr = "127.0.0.1:8181".parse().unwrap();
        let reachable: SocketAddr = "192.0.2.10:8181".parse().unwrap();
        assert!(discloses_host_details(loopback, ApiSurface::Full));
        assert!(!discloses_host_details(loopback, ApiSurface::LanChatOnly));
        assert!(!discloses_host_details(reachable, ApiSurface::Full));
    }
}

fn health_backend(
    gemma4_available: bool,
    runnable_serve_ready: bool,
    dg_serve_ready: bool,
    model_loaded: bool,
) -> &'static str {
    if gemma4_available {
        "gemma4-runtime"
    } else if runnable_serve_ready {
        "runnable-runtime"
    } else if dg_serve_ready {
        "diffusion-gemma-runtime"
    } else if model_loaded {
        "llama"
    } else {
        "none"
    }
}

#[cfg(test)]
mod gemma4_serve_lane_health_tests {
    use super::*;

    #[test]
    fn health_lane_is_active_model_scoped_and_serializes_stable_values() {
        let lanes = HashMap::from([
            ("ghost".to_string(), Gemma4ServeLane::GhostMoe),
            ("local".to_string(), Gemma4ServeLane::Local),
            ("distributed".to_string(), Gemma4ServeLane::Distributed),
        ]);
        assert_eq!(
            active_gemma4_serve_lane(Some("ghost"), &lanes),
            Some(Gemma4ServeLane::GhostMoe)
        );
        assert_eq!(
            active_gemma4_serve_lane(Some("distributed"), &lanes),
            Some(Gemma4ServeLane::Distributed)
        );
        assert_eq!(active_gemma4_serve_lane(Some("other"), &lanes), None);
        assert_eq!(active_gemma4_serve_lane(None, &lanes), None);

        for (lane, expected) in [
            (Gemma4ServeLane::GhostMoe, "ghost_moe"),
            (Gemma4ServeLane::Local, "local"),
            (Gemma4ServeLane::Distributed, "distributed"),
        ] {
            assert_eq!(serde_json::to_value(lane).unwrap(), expected);
        }
        assert_eq!(serde_json::to_value(Gemma4ServeLane::Cuda).unwrap(), "cuda");
        for (mode, expected) in [
            (
                Gemma4GhostExecutionMode::FullCommonMetal,
                "full_common_metal",
            ),
            (Gemma4GhostExecutionMode::HybridMetal, "hybrid_metal"),
            (Gemma4GhostExecutionMode::FullCommonCuda, "full_common_cuda"),
            (Gemma4GhostExecutionMode::HybridCuda, "hybrid_cuda"),
            (Gemma4GhostExecutionMode::CpuStorage, "cpu_storage"),
        ] {
            assert_eq!(serde_json::to_value(mode).unwrap(), expected);
        }
        for (backend, expected) in [
            (Gemma4GhostBackend::Cpu, "cpu"),
            (Gemma4GhostBackend::Metal, "metal"),
            (Gemma4GhostBackend::Cuda, "cuda"),
        ] {
            assert_eq!(serde_json::to_value(backend).unwrap(), expected);
        }
    }

    #[test]
    fn busy_health_never_reuses_a_stale_gemma4_lane() {
        let value = serde_json::to_value(busy_health_response(&AppState::default())).unwrap();
        assert_eq!(value["gemma4_serve_lane"], serde_json::Value::Null);
        assert_eq!(
            value["gemma4_ghost_common_metal_active"],
            serde_json::Value::Null
        );
        assert_eq!(
            value["gemma4_ghost_execution_mode"],
            serde_json::Value::Null
        );
        assert_eq!(
            value["gemma4_ghost_experts_metal_active"],
            serde_json::Value::Null
        );
        assert_eq!(
            value["gemma4_ghost_head_metal_active"],
            serde_json::Value::Null
        );
        assert_eq!(value["gemma4_ghost_backend"], serde_json::Value::Null);
        assert_eq!(
            value["gemma4_ghost_experts_gpu_active"],
            serde_json::Value::Null
        );
        assert_eq!(value["gemma4_available"], false);
        assert_eq!(value["generation_ready"], false);
    }

    #[tokio::test]
    async fn unloaded_health_clears_ghost_common_metal_claim() {
        let value =
            serde_json::to_value(health_registry_snapshot(&AppState::default()).await).unwrap();
        assert_eq!(value["loaded_now"], false);
        assert_eq!(value["gemma4_serve_lane"], serde_json::Value::Null);
        assert_eq!(
            value["gemma4_ghost_common_metal_active"],
            serde_json::Value::Null
        );
        assert_eq!(
            value["gemma4_ghost_execution_mode"],
            serde_json::Value::Null
        );
        assert_eq!(
            value["gemma4_ghost_experts_metal_active"],
            serde_json::Value::Null
        );
        assert_eq!(
            value["gemma4_ghost_head_metal_active"],
            serde_json::Value::Null
        );
    }

    #[test]
    fn ghost_execution_health_reports_full_hybrid_and_cpu_components() {
        use crate::gemma4_runtime::{
            Gemma4GhostCudaComponents as Cuda, Gemma4GhostMetalComponents as Metal,
        };
        use Gemma4ServeLane::{Distributed, GhostMoe};

        assert_eq!(
            gemma4_ghost_execution_health(
                Some(Distributed),
                true,
                Metal {
                    common: true,
                    experts: true,
                    head: true,
                },
                Cuda::default(),
                true,
                false,
            ),
            None
        );
        assert_eq!(
            gemma4_ghost_execution_health(
                Some(GhostMoe),
                false,
                Metal {
                    common: true,
                    experts: true,
                    head: true,
                },
                Cuda::default(),
                true,
                false,
            ),
            None
        );
        assert_eq!(
            gemma4_ghost_execution_health(
                Some(GhostMoe),
                true,
                Metal::default(),
                Cuda::default(),
                true,
                false,
            ),
            Some(Gemma4GhostExecutionHealth {
                mode: Gemma4GhostExecutionMode::CpuStorage,
                backend: Gemma4GhostBackend::Cpu,
                common_gpu_active: false,
                experts_gpu_active: false,
                head_gpu_active: false,
                common_metal_active: false,
                experts_metal_active: false,
                head_metal_active: false,
            })
        );
        assert_eq!(
            gemma4_ghost_execution_health(
                Some(GhostMoe),
                true,
                Metal {
                    common: false,
                    experts: true,
                    head: true,
                },
                Cuda::default(),
                true,
                false,
            ),
            Some(Gemma4GhostExecutionHealth {
                mode: Gemma4GhostExecutionMode::HybridMetal,
                backend: Gemma4GhostBackend::Metal,
                common_gpu_active: false,
                experts_gpu_active: true,
                head_gpu_active: true,
                common_metal_active: false,
                experts_metal_active: true,
                head_metal_active: true,
            })
        );
        assert_eq!(
            gemma4_ghost_execution_health(
                Some(GhostMoe),
                true,
                Metal {
                    common: true,
                    experts: true,
                    head: true,
                },
                Cuda::default(),
                false,
                false,
            ),
            Some(Gemma4GhostExecutionHealth {
                mode: Gemma4GhostExecutionMode::CpuStorage,
                backend: Gemma4GhostBackend::Cpu,
                common_gpu_active: false,
                experts_gpu_active: false,
                head_gpu_active: false,
                common_metal_active: false,
                experts_metal_active: false,
                head_metal_active: false,
            })
        );
        assert_eq!(
            gemma4_ghost_execution_health(
                Some(GhostMoe),
                true,
                Metal {
                    common: true,
                    experts: true,
                    head: false,
                },
                Cuda::default(),
                true,
                false,
            ),
            Some(Gemma4GhostExecutionHealth {
                mode: Gemma4GhostExecutionMode::FullCommonMetal,
                backend: Gemma4GhostBackend::Metal,
                common_gpu_active: true,
                experts_gpu_active: true,
                head_gpu_active: false,
                common_metal_active: true,
                experts_metal_active: true,
                head_metal_active: false,
            })
        );
        assert_eq!(
            gemma4_ghost_execution_health(
                Some(GhostMoe),
                true,
                Metal::default(),
                Cuda {
                    common: false,
                    experts: true,
                    head: true,
                },
                true,
                false,
            ),
            Some(Gemma4GhostExecutionHealth {
                mode: Gemma4GhostExecutionMode::HybridCuda,
                backend: Gemma4GhostBackend::Cuda,
                common_gpu_active: false,
                experts_gpu_active: true,
                head_gpu_active: true,
                common_metal_active: false,
                experts_metal_active: false,
                head_metal_active: false,
            })
        );
        assert_eq!(
            gemma4_ghost_execution_health(
                Some(GhostMoe),
                true,
                Metal::default(),
                Cuda {
                    common: true,
                    experts: true,
                    head: true,
                },
                true,
                false,
            )
            .unwrap()
            .mode,
            Gemma4GhostExecutionMode::FullCommonCuda,
        );
        assert_eq!(
            gemma4_ghost_execution_health(
                Some(GhostMoe),
                true,
                Metal::default(),
                Cuda {
                    common: false,
                    experts: false,
                    head: true,
                },
                true,
                true,
            )
            .unwrap()
            .mode,
            Gemma4GhostExecutionMode::CpuStorage,
            "deterministic mode disables every accelerator component",
        );
    }

    #[test]
    fn ghost_execution_health_serializes_mode_and_false_components() {
        let mut response = busy_health_response(&AppState::default());
        response.gemma4_ghost_common_metal_active = Some(false);
        response.gemma4_ghost_execution_mode = Some(Gemma4GhostExecutionMode::HybridMetal);
        response.gemma4_ghost_experts_metal_active = Some(true);
        response.gemma4_ghost_head_metal_active = Some(false);
        response.gemma4_ghost_backend = Some(Gemma4GhostBackend::Metal);
        response.gemma4_ghost_common_gpu_active = Some(false);
        response.gemma4_ghost_experts_gpu_active = Some(true);
        response.gemma4_ghost_head_gpu_active = Some(false);
        let value = serde_json::to_value(&response).unwrap();
        assert_eq!(value["gemma4_ghost_common_metal_active"], false);
        assert_eq!(value["gemma4_ghost_execution_mode"], "hybrid_metal");
        assert_eq!(value["gemma4_ghost_experts_metal_active"], true);
        assert_eq!(value["gemma4_ghost_head_metal_active"], false);
        assert_eq!(value["gemma4_ghost_backend"], "metal");
        assert_eq!(value["gemma4_ghost_experts_gpu_active"], true);

        response.gemma4_ghost_common_metal_active = Some(true);
        response.gemma4_ghost_execution_mode = Some(Gemma4GhostExecutionMode::FullCommonMetal);
        let value = serde_json::to_value(response).unwrap();
        assert_eq!(value["gemma4_ghost_common_metal_active"], true);
        assert_eq!(value["gemma4_ghost_execution_mode"], "full_common_metal");
    }
}

async fn llama_server_models(
    State(state): State<AppState>,
    Query(query): Query<LlamaServerReadOnlyQuery>,
) -> Response {
    if let Some(response) =
        unsupported_llama_server_query_params("/models", &query.unsupported_fields)
    {
        return response;
    }

    let loaded = state.loaded_models.read().await;
    let data = loaded
        .values()
        .map(|model| LlamaServerModelListItem {
            id: model.id.clone(),
            path: None,
            status: LlamaServerModelStatus {
                value: "loaded",
                args: Vec::new(),
            },
            architecture: LlamaServerModelArchitecture {
                input_modalities: vec!["text"],
                output_modalities: vec!["text"],
            },
            camelid: LlamaServerModelCamelid {
                generation_ready: loaded_model_generation_ready(model),
                model_path_redacted: true,
            },
        })
        .collect();

    Json(LlamaServerModelListResponse {
        data,
        camelid: LlamaServerModelListCamelid {
            compatibility: "partial_llama_server_models_read_only",
            scope: "loaded_models_only",
            unsupported: vec![
                "router_model_cache_listing",
                "models_reload",
                "models_autoload",
                "models_unload",
                "multimodal_architecture_metadata",
            ],
        },
    })
    .into_response()
}

async fn llama_server_models_load(
    State(state): State<AppState>,
    payload: std::result::Result<Json<LlamaServerModelsLoadRequest>, JsonRejection>,
) -> Response {
    let Json(req) = match payload {
        Ok(payload) => payload,
        Err(err) => {
            return api_error(
                StatusCode::BAD_REQUEST,
                "invalid_request_json",
                format!("invalid /models/load JSON request: {err}"),
                Some("body"),
            )
        }
    };

    if !req.unsupported_fields.is_empty() {
        let mut fields: Vec<_> = req.unsupported_fields.keys().cloned().collect();
        fields.sort();
        return api_error(
            StatusCode::BAD_REQUEST,
            "unsupported_parameter",
            format!(
                "unsupported /models/load field(s): {}. Camelid supports only a narrow local load alias with model/path plus optional id; router-mode cache, reload, autoload, and model-management semantics remain unsupported.",
                fields.join(", ")
            ),
            Some("body"),
        );
    }

    if req.model.is_some() && req.path.is_some() {
        return api_error(
            StatusCode::BAD_REQUEST,
            "ambiguous_model_path",
            "POST /models/load accepts either `model` or `path`, not both; send one local GGUF path for the narrow load alias.".to_string(),
            Some("model"),
        );
    }

    let Some(path) = req.model.or(req.path) else {
        return api_error(
            StatusCode::BAD_REQUEST,
            "missing_model_path",
            "POST /models/load requires a local GGUF path in `model` or `path`; router cache names and autoload semantics are not supported.".to_string(),
            Some("model"),
        );
    };

    match load_model_from_path(&state, path, req.id, true).await {
        Ok(loaded) => {
            let item = LlamaServerModelListItem {
                id: loaded.id.clone(),
                path: None,
                status: LlamaServerModelStatus {
                    value: "loaded",
                    args: Vec::new(),
                },
                architecture: LlamaServerModelArchitecture {
                    input_modalities: vec!["text"],
                    output_modalities: vec!["text"],
                },
                camelid: LlamaServerModelCamelid {
                    generation_ready: loaded_model_generation_ready(&loaded),
                    model_path_redacted: true,
                },
            };
            Json(LlamaServerModelLoadResponse {
                data: item,
                camelid: LlamaServerModelLoadCamelid {
                    compatibility: "partial_llama_server_models_load_local_path",
                    scope: "single_local_model_load_alias",
                    model_path_redacted: true,
                    unsupported: vec![
                        "router_model_cache_listing",
                        "models_reload",
                        "models_autoload",
                        "models_unload",
                        "multimodal_architecture_metadata",
                        "full_llama_server_model_management",
                    ],
                },
            })
            .into_response()
        }
        Err(err) => llama_server_models_load_error(err),
    }
}

fn llama_server_models_load_error(err: BackendError) -> Response {
    let code = backend_error_code(&err);
    let message = match err {
        BackendError::Io { source, .. } => {
            // Redaction contract for this llama-server alias: never echo local
            // path detail. The resolver's io source now enumerates every
            // attempted location (useful on the native endpoint), so only the
            // pathless error kind may pass through here.
            format!(
                "failed to load requested local GGUF path: {}",
                source.kind()
            )
        }
        other => other.to_string(),
    };
    api_error(StatusCode::BAD_REQUEST, code, message, Some("model"))
}

async fn unsupported_llama_server_models_unload() -> Response {
    unsupported_route(
        "unsupported_llama_server_models_unload",
        "POST /models/unload is not supported yet; Camelid keeps native llama-server router-mode model unloading separate from the stable /api/models/unload path until router semantics and support-contract behavior are implemented and tested",
        Some("model"),
    )
}

fn unsupported_llama_server_query_params(
    route: &'static str,
    fields: &HashMap<String, String>,
) -> Option<Response> {
    if fields.is_empty() {
        return None;
    }

    let mut fields = fields.keys().map(String::as_str).collect::<Vec<_>>();
    fields.sort_unstable();
    Some(api_error(
        StatusCode::BAD_REQUEST,
        "unsupported_parameter",
        format!(
            "{route} query parameter(s) are not supported yet: {}; Camelid exposes this route as active-model read-only discovery, not llama-server router-mode autoload/reload/model selection",
            fields.join(", ")
        ),
        Some("query"),
    ))
}

async fn llama_server_props(
    State(state): State<AppState>,
    Query(query): Query<LlamaServerReadOnlyQuery>,
) -> Response {
    if let Some(response) =
        unsupported_llama_server_query_params("/props", &query.unsupported_fields)
    {
        return response;
    }

    let active_id_lock = state.active_model_id.read().await;
    let loaded_models = state.loaded_models.read().await;
    let model = active_id_lock.as_ref().and_then(|id| loaded_models.get(id));
    let generation_ready = model.is_some_and(loaded_model_generation_ready);
    let n_ctx = model
        .and_then(|model| model.llama_config.as_ref())
        .map(|config| config.context_length)
        .unwrap_or(0);
    let chat_template = model
        .and_then(|model| model.tokenizer_runtime.as_ref())
        .and_then(|tokenizer| tokenizer.chat_template.clone());
    let chat_template_caps = llama_server_chat_template_caps(model);
    let model_id = model.map(|model| model.id.clone());

    Json(LlamaServerPropsResponse {
        default_generation_settings: LlamaServerDefaultGenerationSettings {
            id: 0,
            id_task: -1,
            n_ctx,
            speculative: false,
            is_processing: false,
            params: LlamaServerDefaultGenerationParams {
                n_predict: -1,
                seed: u32::MAX,
                temperature: 0.0,
                top_k: 0,
                top_p: 1.0,
                presence_penalty: 0.0,
                frequency_penalty: 0.0,
                stop: Vec::new(),
                max_tokens: -1,
                ignore_eos: false,
                stream: true,
                n_probs: 0,
                samplers: vec!["greedy"],
            },
            prompt: "",
            next_token: LlamaServerNextTokenProps {
                has_next_token: generation_ready,
                has_new_line: false,
                n_remain: -1,
                n_decoded: 0,
                stopping_word: "",
            },
        },
        // In llama-server semantics `total_slots` is the length of the `/slots`
        // array, and `GET /slots?fail_on_no_slot=1` arbitrates against those same
        // slots — so all three answer from `EngineHandle::total_slots`, which is
        // the cooperative capacity except on the CUDA resident lane, where every
        // stream runs exclusive and the honest answer is 1.
        total_slots: state.engine.total_slots().try_into().unwrap_or(u32::MAX),
        model_path: None,
        model_id,
        chat_template,
        chat_template_caps,
        modalities: LlamaServerModalities { vision: false },
        build_info: "camelid",
        is_sleeping: false,
        camelid: LlamaServerPropsCamelid {
            compatibility: "partial_llama_server_props_read_only",
            generation_ready,
            model_path_redacted: true,
            unsupported: vec![
                "post_props",
                "post_slots",
                "slot_cache_actions",
                "native_completion",
                "native_completion_streaming",
                "full_native_completion_parity",
                "embeddings",
                "reranking",
                "multimodal",
            ],
        },
    })
    .into_response()
}

fn llama_server_chat_template_caps(model: Option<&LoadedModel>) -> serde_json::Value {
    if let Some(model) = model.filter(|model| model.gguf.architecture() == Some("smollm3")) {
        let template = model
            .tokenizer_runtime
            .as_deref()
            .and_then(|tokenizer| tokenizer.chat_template.as_deref());
        return match template {
            Some(template) if is_exact_smollm3_chat_template(template) => serde_json::json!({
                "available": true,
                "requires_loaded_model": true,
                "source": "tokenizer.chat_template",
                "detected_format": "smollm3_exact_default_thinking_text_qualified",
                "length": template.len(),
                "supported_operations": ["render_prompt"],
                "render_prompt_envelope": {
                    "public_surfaces": {
                        "/apply-template": {
                            "thinking": ["omitted_effective_true"]
                        },
                        "/v1/chat/completions": {
                            "thinking": ["omitted_defaults_true", "explicit_true"],
                            "streaming": [false, true]
                        }
                    },
                    "content": "text_only",
                    "roles": ["user", "assistant"],
                    "history": "strict_alternation_ending_user",
                    "add_generation_prompt": true,
                    "today_date": "system_local_english_dd_month_yyyy"
                },
                "unsupported": [
                    "system_messages",
                    "custom_instructions",
                    "system_override",
                    "tools",
                    "tool_messages",
                    "thinking_disabled",
                    "invalid_roles",
                    "non_alternating_history",
                    "history_not_ending_user",
                    "multimodal_content",
                    "non_text_content",
                    "arbitrary_template_kwargs",
                    "full_llama_server_template_parity"
                ],
            }),
            Some(template) => serde_json::json!({
                "available": true,
                "requires_loaded_model": true,
                "source": "tokenizer.chat_template",
                "detected_format": detect_chat_template_format(template),
                "length": template.len(),
                "supported_operations": [],
                "render_prompt_envelope": null,
                "unsupported": [
                    "smollm3_exact_template_required",
                    "render_prompt",
                    "arbitrary_template_kwargs",
                    "tool_call_templates",
                    "multimodal_templates",
                    "full_llama_server_template_parity"
                ],
            }),
            None => serde_json::json!({
                "available": false,
                "requires_loaded_model": true,
                "source": null,
                "detected_format": null,
                "length": null,
                "supported_operations": [],
                "render_prompt_envelope": null,
                "unsupported": [
                    "smollm3_chat_template_missing",
                    "render_prompt",
                    "arbitrary_template_kwargs",
                    "tool_call_templates",
                    "multimodal_templates",
                    "full_llama_server_template_parity"
                ],
            }),
        };
    }

    if let Some((model, template)) = model.and_then(|model| {
        (model.gguf.architecture() != Some("smollm3"))
            .then_some(model)
            .and_then(|model| {
                model
                    .tokenizer_runtime
                    .as_deref()
                    .and_then(|tokenizer| tokenizer.chat_template.as_deref())
                    .filter(|template| is_exact_smollm3_chat_template(template))
                    .map(|template| (model, template))
            })
    }) {
        return serde_json::json!({
            "available": true,
            "requires_loaded_model": true,
            "source": "tokenizer.chat_template",
            "detected_format": "smollm3_exact_template_architecture_mismatch",
            "length": template.len(),
            "declared_architecture": model.gguf.architecture(),
            "supported_operations": [],
            "render_prompt_envelope": null,
            "unsupported": [
                "smollm3_architecture_template_mismatch",
                "render_prompt",
                "arbitrary_template_kwargs",
                "tool_call_templates",
                "multimodal_templates",
                "full_llama_server_template_parity"
            ],
        });
    }

    let template = model.and_then(|model| match &model.tokenizer {
        TokenizerLoadState::Available(summary) => summary.chat_template.as_ref(),
        TokenizerLoadState::Unavailable { .. } => None,
    });

    match template {
        Some(template) => serde_json::json!({
            "available": true,
            "requires_loaded_model": true,
            "source": template.source,
            "detected_format": template.detected_format,
            "length": template.length,
            "supported_operations": ["render_prompt"],
            "unsupported": [
                "arbitrary_template_kwargs",
                "tool_call_templates",
                "multimodal_templates",
                "full_llama_server_template_parity"
            ],
        }),
        None => serde_json::json!({
            "available": false,
            "requires_loaded_model": true,
            "source": null,
            "detected_format": null,
            "length": null,
            "supported_operations": [],
            "unsupported": [
                "no_loaded_supported_chat_template",
                "arbitrary_template_kwargs",
                "tool_call_templates",
                "multimodal_templates",
                "full_llama_server_template_parity"
            ],
        }),
    }
}

