#[derive(Debug, Deserialize)]
#[serde(untagged)]
enum EmbeddingInput {
    Text(String),
    Batch(Vec<String>),
}

impl EmbeddingInput {
    fn into_batch(self) -> Vec<String> {
        match self {
            Self::Text(text) => vec![text],
            Self::Batch(batch) => batch,
        }
    }
}

#[derive(Debug, Deserialize)]
struct EmbeddingRequest {
    #[serde(default)]
    model: Option<String>,
    input: EmbeddingInput,
    #[serde(default)]
    encoding_format: Option<String>,
    #[serde(default)]
    dimensions: Option<usize>,
    #[serde(default)]
    user: Option<String>,
}

#[derive(Debug, Serialize)]
struct EmbeddingData {
    object: &'static str,
    embedding: Vec<f32>,
    index: usize,
}

#[derive(Debug, Serialize)]
struct EmbeddingUsage {
    prompt_tokens: usize,
    total_tokens: usize,
}

#[derive(Debug, Serialize)]
struct EmbeddingResponse {
    object: &'static str,
    data: Vec<EmbeddingData>,
    model: String,
    usage: EmbeddingUsage,
}

#[derive(Debug, Deserialize)]
#[serde(untagged)]
enum RerankDocument {
    Text(String),
    Object { text: String },
}

impl RerankDocument {
    fn text(&self) -> &str {
        match self {
            Self::Text(text) | Self::Object { text } => text,
        }
    }
}

#[derive(Debug, Deserialize)]
struct RerankRequest {
    #[serde(default)]
    model: Option<String>,
    query: String,
    documents: Vec<RerankDocument>,
    #[serde(default)]
    top_n: Option<usize>,
    #[serde(default)]
    return_documents: bool,
}

#[derive(Debug, Serialize)]
struct RerankResultDocument<'a> {
    text: &'a str,
}

#[derive(Debug, Serialize)]
struct RerankResult<'a> {
    index: usize,
    relevance_score: f32,
    #[serde(skip_serializing_if = "Option::is_none")]
    document: Option<RerankResultDocument<'a>>,
}

#[derive(Debug, Serialize)]
struct RerankResponse<'a> {
    id: String,
    model: String,
    results: Vec<RerankResult<'a>>,
    usage: EmbeddingUsage,
}

async fn resolve_embedding_runtime(
    state: &AppState,
    requested_model: Option<&str>,
) -> std::result::Result<(String, Arc<EmbeddingRuntime>), Response> {
    let model_id = match requested_model
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        Some(model_id) => model_id.to_string(),
        None => {
            let active = state.active_model_id.read().await.clone();
            let loaded = state.loaded_models.read().await;
            let active_embedding = active.filter(|id| {
                loaded
                    .get(id)
                    .is_some_and(|model| is_embedding_model(&model.gguf))
            });
            active_embedding
                .or_else(|| {
                    let mut candidates = loaded
                        .values()
                        .filter(|model| is_embedding_model(&model.gguf))
                        .map(|model| model.id.clone())
                        .collect::<Vec<_>>();
                    candidates.sort();
                    candidates.into_iter().next()
                })
                .ok_or_else(|| {
                    api_error(
                        StatusCode::NOT_FOUND,
                        "model_not_loaded",
                        "load a supported embedding model before requesting embeddings".to_string(),
                        Some("model"),
                    )
                })?
        }
    };
    if let Some(runtime) = state
        .embedding_runtimes
        .read()
        .await
        .get(&model_id)
        .cloned()
    {
        return Ok((model_id, runtime));
    }
    let _load = state.embedding_runtime_load.lock().await;
    if let Some(runtime) = state
        .embedding_runtimes
        .read()
        .await
        .get(&model_id)
        .cloned()
    {
        return Ok((model_id, runtime));
    }

    let model = state
        .loaded_models
        .read()
        .await
        .get(&model_id)
        .cloned()
        .ok_or_else(|| {
            api_error(
                StatusCode::NOT_FOUND,
                "model_not_found",
                format!("model {model_id:?} is not loaded"),
                Some("model"),
            )
        })?;
    if !is_embedding_model(&model.gguf) {
        return Err(api_error(
            StatusCode::UNPROCESSABLE_ENTITY,
            "model_not_embedding_capable",
            format!(
                "model {model_id:?} uses architecture {:?} and name {:?}; it is not an admitted embedding artifact",
                model.gguf.architecture().unwrap_or("unknown"),
                model.gguf.model_name().unwrap_or("unknown")
            ),
            Some("model"),
        ));
    }

    let path = model.path.clone();
    let _reader = state.model_file_lifecycle.read().await;
    let loaded = tokio::task::spawn_blocking(move || EmbeddingRuntime::load(path)).await;
    let runtime = match loaded {
        Ok(Ok(runtime)) => Arc::new(runtime),
        Ok(Err(error)) => {
            return Err(api_error(
                StatusCode::UNPROCESSABLE_ENTITY,
                backend_error_code(&error),
                error.to_string(),
                Some("model"),
            ))
        }
        Err(error) => {
            return Err(api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "embedding_runtime_task_failed",
                format!("embedding runtime load task failed: {error}"),
                Some("model"),
            ))
        }
    };
    let runtime = {
        let mut runtimes = state.embedding_runtimes.write().await;
        runtimes
            .entry(model_id.clone())
            .or_insert_with(|| runtime.clone())
            .clone()
    };
    Ok((model_id, runtime))
}

async fn embeddings(
    State(state): State<AppState>,
    payload: std::result::Result<Json<EmbeddingRequest>, JsonRejection>,
) -> Response {
    let Json(request) = match payload {
        Ok(request) => request,
        Err(error) => return malformed_json_error(error),
    };
    if let Some(format) = request.encoding_format.as_deref() {
        if format != "float" {
            return api_error(
                StatusCode::BAD_REQUEST,
                "unsupported_embedding_encoding",
                "encoding_format must be \"float\"; base64 output is not implemented".to_string(),
                Some("encoding_format"),
            );
        }
    }
    let _ = request.user;
    let inputs = request.input.into_batch();
    if inputs.is_empty() {
        return api_error(
            StatusCode::BAD_REQUEST,
            "empty_embedding_input",
            "input must contain at least one string".to_string(),
            Some("input"),
        );
    }
    let (model_id, runtime) =
        match resolve_embedding_runtime(&state, request.model.as_deref()).await {
            Ok(resolved) => resolved,
            Err(response) => return response,
        };
    let dimensions = request.dimensions;
    if let Err(error) = runtime.validate_dimensions(dimensions) {
        return api_error(
            StatusCode::UNPROCESSABLE_ENTITY,
            backend_error_code(&error),
            error.to_string(),
            Some("dimensions"),
        );
    }
    let result = tokio::task::spawn_blocking(move || {
        let embeddings = runtime.embed_batch(&inputs, dimensions)?;
        let prompt_tokens = inputs
            .iter()
            .map(|input| {
                runtime
                    .tokenizer()
                    .encode(input, true, false)
                    .map(|ids| ids.len())
            })
            .collect::<crate::Result<Vec<_>>>()?
            .into_iter()
            .sum();
        Ok::<_, BackendError>((embeddings, prompt_tokens))
    })
    .await;
    let (embeddings, prompt_tokens) = match result {
        Ok(Ok(result)) => result,
        Ok(Err(error)) => {
            return api_error(
                StatusCode::UNPROCESSABLE_ENTITY,
                backend_error_code(&error),
                error.to_string(),
                Some("input"),
            )
        }
        Err(error) => {
            return api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "embedding_task_failed",
                format!("embedding task failed: {error}"),
                None,
            )
        }
    };
    (
        StatusCode::OK,
        Json(EmbeddingResponse {
            object: "list",
            data: embeddings
                .into_iter()
                .enumerate()
                .map(|(index, embedding)| EmbeddingData {
                    object: "embedding",
                    embedding,
                    index,
                })
                .collect(),
            model: model_id,
            usage: EmbeddingUsage {
                prompt_tokens,
                total_tokens: prompt_tokens,
            },
        }),
    )
        .into_response()
}

async fn rerank(
    State(state): State<AppState>,
    payload: std::result::Result<Json<RerankRequest>, JsonRejection>,
) -> Response {
    let Json(request) = match payload {
        Ok(request) => request,
        Err(error) => return malformed_json_error(error),
    };
    if request.query.trim().is_empty() {
        return api_error(
            StatusCode::BAD_REQUEST,
            "empty_rerank_query",
            "query must not be empty".to_string(),
            Some("query"),
        );
    }
    if request.documents.is_empty() {
        return api_error(
            StatusCode::BAD_REQUEST,
            "empty_rerank_documents",
            "documents must contain at least one item".to_string(),
            Some("documents"),
        );
    }
    let top_n = request.top_n.unwrap_or(request.documents.len());
    if top_n == 0 || top_n > request.documents.len() {
        return api_error(
            StatusCode::BAD_REQUEST,
            "invalid_rerank_top_n",
            format!(
                "top_n must be between 1 and the document count ({}), got {top_n}",
                request.documents.len()
            ),
            Some("top_n"),
        );
    }
    let (model_id, runtime) =
        match resolve_embedding_runtime(&state, request.model.as_deref()).await {
            Ok(resolved) => resolved,
            Err(response) => return response,
        };

    let mut inputs = Vec::with_capacity(request.documents.len() + 1);
    inputs.push(runtime.prepare_retrieval_query(&request.query));
    inputs.extend(
        request
            .documents
            .iter()
            .map(|document| runtime.prepare_retrieval_document(document.text())),
    );
    let result = tokio::task::spawn_blocking(move || {
        let embeddings = runtime.embed_batch(&inputs, None)?;
        let prompt_tokens = inputs
            .iter()
            .map(|input| {
                runtime
                    .tokenizer()
                    .encode(input, true, false)
                    .map(|ids| ids.len())
            })
            .collect::<crate::Result<Vec<_>>>()?
            .into_iter()
            .sum();
        Ok::<_, BackendError>((embeddings, prompt_tokens))
    })
    .await;
    let (embeddings, prompt_tokens) = match result {
        Ok(Ok(result)) => result,
        Ok(Err(error)) => {
            return api_error(
                StatusCode::UNPROCESSABLE_ENTITY,
                backend_error_code(&error),
                error.to_string(),
                Some("documents"),
            )
        }
        Err(error) => {
            return api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "rerank_task_failed",
                format!("rerank task failed: {error}"),
                None,
            )
        }
    };
    let query = &embeddings[0];
    let mut ranked = embeddings[1..]
        .iter()
        .enumerate()
        .map(|(index, document)| cosine_similarity(query, document).map(|score| (index, score)))
        .collect::<crate::Result<Vec<_>>>();
    let ranked = match ranked.as_mut() {
        Ok(ranked) => {
            ranked.sort_by(|left, right| {
                right
                    .1
                    .total_cmp(&left.1)
                    .then_with(|| left.0.cmp(&right.0))
            });
            ranked
        }
        Err(error) => {
            return api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                backend_error_code(error),
                error.to_string(),
                None,
            )
        }
    };
    let results = ranked
        .iter()
        .take(top_n)
        .map(|(index, relevance_score)| RerankResult {
            index: *index,
            relevance_score: *relevance_score,
            document: request.return_documents.then(|| RerankResultDocument {
                text: request.documents[*index].text(),
            }),
        })
        .collect();
    (
        StatusCode::OK,
        Json(RerankResponse {
            id: format!("rerank-{}", uuid::Uuid::new_v4()),
            model: model_id,
            results,
            usage: EmbeddingUsage {
                prompt_tokens,
                total_tokens: prompt_tokens,
            },
        }),
    )
        .into_response()
}

