    #[test]
    fn runnable_request_tools_respects_tool_choice_none() {
        let with_choice = |tool_choice: Option<&str>| {
            let mut request = serde_json::json!({
                "model": "m",
                "messages": [{"role": "user", "content": "hi"}],
                "tools": [{
                    "type": "function",
                    "function": {"name": "weather", "parameters": {"type": "object"}}
                }]
            });
            if let Some(choice) = tool_choice {
                request["tool_choice"] = serde_json::json!(choice);
            }
            serde_json::from_value::<ChatCompletionRequest>(request).unwrap()
        };
        assert!(
            runnable_request_tools(&with_choice(Some("none"))).is_empty(),
            "tool_choice none must disable rendering and envelope holding"
        );
        let tools = runnable_request_tools(&with_choice(None));
        assert_eq!(tools.len(), 1);
        assert_eq!(tools[0]["name"], "weather");
    }

    #[test]
    fn runnable_preflight_and_chat_normalize_the_same_tool_schema_into_the_prompt() {
        let wrapped_tool = serde_json::json!({
            "type": "function",
            "function": {
                "name": "read_file",
                "description": "Read a workspace file",
                "parameters": {
                    "type": "object",
                    "properties": {"path": {"type": "string"}},
                    "required": ["path"]
                }
            }
        });
        let chat: ChatCompletionRequest = serde_json::from_value(serde_json::json!({
            "model": "ornith",
            "messages": [{"role": "user", "content": "read notes.txt"}],
            "tools": [wrapped_tool.clone()]
        }))
        .unwrap();
        let preflight: GenerationSessionRequest = serde_json::from_value(serde_json::json!({
            "model": "ornith",
            "messages": [{"role": "user", "content": "read notes.txt"}],
            "tools": [wrapped_tool]
        }))
        .unwrap();

        let chat_tools = runnable_request_tools(&chat);
        let preflight_tools = normalize_runnable_tools(preflight.tools.as_deref(), true);
        assert_eq!(preflight_tools, chat_tools);
        assert_eq!(preflight_tools[0]["name"], "read_file");
        assert!(preflight_tools[0].get("function").is_none());

        let messages = preflight.messages.as_deref().unwrap();
        let chat_prompt = render_ornith_chatml_prompt_with_tools(messages, &chat_tools, false);
        let preflight_prompt =
            render_ornith_chatml_prompt_with_tools(messages, &preflight_tools, false);
        assert_eq!(preflight_prompt, chat_prompt);
        let rendered_tool = preflight_prompt
            .split_once("<tools>\n")
            .and_then(|(_, rest)| rest.split_once("\n</tools>"))
            .map(|(tool, _)| tool)
            .expect("the runnable tool renderer emits one JSON object in the tools block");
        assert_eq!(
            serde_json::from_str::<serde_json::Value>(rendered_tool).unwrap(),
            preflight_tools[0]
        );
        assert!(preflight_prompt.ends_with("<|im_start|>assistant\n<think>\n\n</think>\n\n"));
    }

    #[test]
    fn response_format_maps_to_constraint() {
        use serde_json::json;
        // json_object and a supported json_schema enable constrained decoding;
        // text / absent leave it off.
        assert!(
            constraint_from_response_format(Some(&json!({"type": "json_object"})))
                .unwrap()
                .is_some()
        );
        assert!(
            constraint_from_response_format(Some(&json!({"type": "text"})))
                .unwrap()
                .is_none()
        );
        assert!(constraint_from_response_format(None).unwrap().is_none());
        assert!(constraint_from_response_format(Some(&json!(null)))
            .unwrap()
            .is_none());
        // A supported json_schema compiles.
        let good = json!({
            "type": "json_schema",
            "json_schema": {"name": "x", "schema": {
                "type": "object", "additionalProperties": false,
                "properties": {"a": {"type": "string"}}, "required": ["a"]
            }}
        });
        assert!(constraint_from_response_format(Some(&good))
            .unwrap()
            .is_some());
        // Scalar roots and advanced keywords are supported by LLGuidance.
        let broad = json!({
            "type": "json_schema",
            "json_schema": {"schema": {
                "type": "string", "pattern": "^[a-z]+$", "minLength": 2
            }}
        });
        assert!(constraint_from_response_format(Some(&broad))
            .unwrap()
            .is_some());
        // A schema LLGuidance cannot compile is a typed error, not ignored.
        let bad = json!({"type": "json_schema", "json_schema": {"schema": {"type": "camel"}}});
        assert!(constraint_from_response_format(Some(&bad)).is_err());
        // Lark CFGs are accepted through response_format and the llama.cpp-style
        // top-level field; malformed grammars fail closed.
        assert!(constraint_from_response_format(Some(
            &json!({"type": "grammar", "grammar": "start: \"yes\" | \"no\""})
        ))
        .unwrap()
        .is_some());
        assert!(constraint_from_response_format(Some(
            &json!({"type": "grammar", "grammar": "start: ("})
        ))
        .is_err());
        assert!(constraint_from_request(None, None, Some("start: \"ok\""))
            .unwrap()
            .is_some());
        assert!(constraint_from_request(
            Some(&json!({"type": "json_object"})),
            Some(&json!({"type": "string"})),
            None,
        )
        .is_err());
        // A json_schema without the schema payload is an error.
        assert!(constraint_from_response_format(Some(&json!({"type": "json_schema"}))).is_err());
        // Unknown response_format types remain errors.
        assert!(constraint_from_response_format(Some(&json!({"type": "yaml"}))).is_err());
    }

